import React, { useEffect, useMemo, useRef, useState } from 'react';
import { useAuth } from '../context/AuthContext';
import api, { inventoryAPI, upgradesAPI, dashboardAPI } from '../services/api';
import ImageWithFallback from '../components/ImageWithFallback';
import './UpgradePage.css';

const REEL_SIZE = 17;
const ANIMATION_MS = 4200;

const chanceFor = (source, target) => source && target
  ? Math.min(95, Math.max(1, Number(source.virtual_value) / Number(target.virtual_value) * 100))
  : 0;

const UpgradePage = () => {
  const { updateBalance } = useAuth();
  const [inventory, setInventory] = useState([]);
  const [allItems, setAllItems] = useState([]);
  const [sourceId, setSourceId] = useState(null);
  const [targetId, setTargetId] = useState(null);
  const [balance, setBalance] = useState(0);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [phase, setPhase] = useState('idle'); // idle | rolling | result
  const [result, setResult] = useState(null);
  const [reel, setReel] = useState([]);
  const reelViewportRef = useRef(null);
  const [reelX, setReelX] = useState(0);

  const refresh = async () => {
    const [inv, items, bal] = await Promise.all([
      inventoryAPI.getInventory(),
      api.get('/items/'),
      dashboardAPI.getBalance(),
    ]);
    setInventory(Array.isArray(inv.data) ? inv.data : []);
    setAllItems(Array.isArray(items.data) ? items.data : []);
    setBalance(Number(bal.data?.balance || 0));
  };

  useEffect(() => {
    refresh().catch(console.error).finally(() => setLoading(false));
  }, []);

  const source = inventory.find((row) => row.item_id === sourceId)?.item || null;
  const targets = useMemo(() => source
    ? allItems.filter((item) => item.id !== source.id && item.is_active !== false && Number(item.virtual_value) > Number(source.virtual_value))
      .sort((a, b) => Number(a.virtual_value) - Number(b.virtual_value))
    : [], [allItems, source]);
  const target = targets.find((item) => item.id === targetId) || null;
  const chance = chanceFor(source, target);

  const makeReel = (targetItem) => {
    if (!targetItem) return [];
    const pool = targets.length ? targets : [targetItem];
    const cells = Array.from({ length: REEL_SIZE }, (_, i) => {
      if (i === Math.floor(REEL_SIZE / 2)) return targetItem;
      return pool[(i * 7 + targetItem.id) % pool.length];
    });
    return cells;
  };

  useEffect(() => {
    if (phase !== 'rolling' || !reel.length) return;
    setReelX(0);
    const timer = window.setTimeout(() => {
      const viewport = reelViewportRef.current?.clientWidth || 560;
      const winnerIndex = Math.floor(REEL_SIZE / 2);
      const winnerCenter = winnerIndex * 130 + 65;
      setReelX(Math.round(viewport / 2 - winnerCenter));
    }, 60);
    return () => window.clearTimeout(timer);
  }, [phase, reel]);

  const selectSource = (id) => {
    if (phase !== 'idle') return;
    setSourceId(id);
    setTargetId(null);
    setResult(null);
    setReel([]);
  };

  const selectTarget = (id) => {
    if (phase !== 'idle') return;
    setTargetId(id);
    setResult(null);
  };

  const runUpgrade = async () => {
    if (!source || !target || busy || phase !== 'idle') return;
    setBusy(true);
    setResult(null);
    try {
      // The server decides success first; the reel only reveals that already-decided result.
      const response = await upgradesAPI.performUpgrade({ original_item_id: source.id, target_item_id: target.id });
      const serverResult = response.data;
      setReel(makeReel(target));
      setPhase('rolling');
      window.setTimeout(async () => {
        setResult(serverResult);
        setPhase('result');
        await refresh();
        await updateBalance();
        setBusy(false);
      }, ANIMATION_MS);
    } catch (error) {
      setBusy(false);
      alert(error.response?.data?.detail || 'Upgrade impossible.');
    }
  };

  const reset = () => {
    setPhase('idle');
    setResult(null);
    setReel([]);
    setSourceId(null);
    setTargetId(null);
  };

  if (loading) return <div className="upgrade-page container py-5"><div className="upgrade-loading"><div className="upgrade-spinner" /><span>Préparation de l’Upgrade…</span></div></div>;

  const resultSuccess = result?.was_successful;
  const displayTarget = target || allItems.find((item) => item.id === result?.target_item_id);

  return (
    <div className="upgrade-page container py-4">
      <div className="upgrade-topbar">
        <div><span className="upgrade-kicker">WELLCASE / UPGRADER</span><h1>Upgrade</h1><p>Mise tout sur une skin plus chère. Le serveur décide, l’animation révèle.</p></div>
        <div className="upgrade-balance"><span>SOLDE</span><strong>{balance.toLocaleString('fr-FR')} €</strong></div>
      </div>

      <div className={`upgrade-stage ${phase}`}>
        <div className="upgrade-card source-card">
          <span className="card-kicker">YOUR SKIN</span>
          {source ? <><div className="upgrade-art"><ImageWithFallback src={source.image_url} alt={source.name} /></div><h3>{source.name}</h3><strong>{Number(source.virtual_value).toLocaleString('fr-FR')} €</strong><small>1 item consommé en cas de tentative</small></> : <div className="upgrade-placeholder">Sélectionne une skin<br/>dans ton inventaire</div>}
        </div>

        <div className="upgrade-core">
          <div className="chance-ring" style={{ '--chance': `${chance}%` }}><div><strong>{chance ? chance.toFixed(1) : '—'}%</strong><span>CHANCE</span></div></div>
          <div className="upgrade-arrow-line"><i /><b>UPGRADE</b><i /></div>
          <div className="upgrade-reel-wrap">
            <div className="reel-pointer" />
            <div className={`upgrade-reel ${phase === 'rolling' ? 'rolling-reel' : ''}`} style={{ transform: `translate3d(${reelX}px,0,0)` }}>
              {reel.length ? reel.map((item, index) => <div className="reel-cell" key={`${item.id}-${index}`}><ImageWithFallback src={item.image_url} alt={item.name} /><span>{item.name}</span><small>{Number(item.virtual_value).toLocaleString('fr-FR')} €</small></div>) : <div className="reel-idle">Sélectionne une cible pour lancer la machine</div>}
            </div>
          </div>
        </div>

        <div className="upgrade-card target-card">
          <span className="card-kicker">TARGET SKIN</span>
          {target ? <><div className="upgrade-art"><ImageWithFallback src={target.image_url} alt={target.name} /></div><h3>{target.name}</h3><strong>{Number(target.virtual_value).toLocaleString('fr-FR')} €</strong><small>{chance.toFixed(1)}% de réussite</small></> : <div className="upgrade-placeholder">Choisis une cible<br/>plus chère</div>}
        </div>
      </div>

      {phase === 'idle' && <>
        <section className="upgrade-selector-grid">
          <div className="selector-panel"><div className="selector-title"><span>01</span><div><b>Choisis ta skin</b><small>Une skin de ton inventaire</small></div></div><div className="skin-grid">{inventory.map((row) => <button key={row.id} className={sourceId === row.item_id ? 'active' : ''} onClick={() => selectSource(row.item_id)}><ImageWithFallback src={row.item?.image_url} alt="" /><div><b>{row.item?.name}</b><span>{Number(row.item?.virtual_value || 0).toLocaleString('fr-FR')} €</span></div>{row.quantity > 1 && <em>x{row.quantity}</em>}</button>)}</div></div>
          <div className="selector-panel"><div className="selector-title"><span>02</span><div><b>Choisis ta cible</b><small>{source ? `${targets.length} skins plus chères disponibles` : 'Sélectionne une skin d’abord'}</small></div></div><div className="skin-grid">{targets.map((item) => <button key={item.id} className={targetId === item.id ? 'active' : ''} onClick={() => selectTarget(item.id)}><ImageWithFallback src={item.image_url} alt="" /><div><b>{item.name}</b><span>{Number(item.virtual_value).toLocaleString('fr-FR')} € · {chanceFor(source, item).toFixed(1)}%</span></div></button>)}</div></div>
        </section>
        <button className="upgrade-main-btn" disabled={!source || !target || busy} onClick={runUpgrade}><span>{busy ? 'PRÉPARATION…' : 'LANCER L’UPGRADE'}</span><small>{target ? `${chance.toFixed(1)}% de chance de gagner` : 'Choisis une skin cible'}</small></button>
      </>}

      {phase === 'rolling' && <div className="upgrade-live"><div className="live-pulse" /><span>UPGRADING</span><strong>La machine choisit ton destin…</strong><small>Résultat sécurisé côté serveur</small></div>}

      {phase === 'result' && result && <div className={`upgrade-result-card ${resultSuccess ? 'success' : 'failure'}`}>
        <div className="result-burst">{resultSuccess ? '✓' : '×'}</div>
        <span>{resultSuccess ? 'UPGRADE SUCCESS' : 'UPGRADE FAILED'}</span>
        <h2>{resultSuccess ? `Tu as obtenu ${displayTarget?.name}` : `Tu as perdu ${source?.name}`}</h2>
        <p>Probabilité : <b>{Number(result.success_chance).toFixed(1)}%</b></p>
        {resultSuccess && displayTarget && <div className="result-art"><ImageWithFallback src={displayTarget.image_url} alt={displayTarget.name} /></div>}
        <button onClick={reset}>NOUVEL UPGRADE</button>
      </div>}
    </div>
  );
};

export default UpgradePage;
